import java.util.*;

class Solution {
    private int sum = 0; // total of all keys visited so far (all larger keys)

    public TreeNode convertBST(TreeNode root) {
        walk(root);
        return root;
    }

    private void walk(TreeNode node) {
        if (node == null) return;
        walk(node.right);  // larger keys first
        sum += node.val;
        node.val = sum;
        walk(node.left);
    }
}

