class Solution:
    def convertBST(self, root: Optional[TreeNode]) -> Optional[TreeNode]:
        acc = 0; st = []; cur = root
        while st or cur:
            while cur: st.append(cur); cur = cur.right
            cur = st.pop(); acc += cur.val; cur.val = acc; cur = cur.left
        return root

