function convertBST(root) {
  const a = []; const go = (n) => { if (!n) return; go(n.left); a.push(n); go(n.right); };
  go(root);
  let s = 0; for (let i = a.length - 1; i >= 0; i--) { s += a[i].val; a[i].val = s; }
  return root;
}
